#include "Parser.h"
#include <array>
#include <cmath>
#include <fstream>
#include <iostream>
#include <iterator>
#include <stdexcept>
#include <string>

int main(int argc, char **argv) {
    try {
        if (argc != 2) return 64;
        std::ifstream input(argv[1]);
        if (!input) return 66;
        const std::string source{std::istreambuf_iterator<char>(input), {}};
        const auto shader = sl_parser::Parser::ParseSource(source);
        if (!shader.properties || shader.properties->size() != 1 ||
            shader.sub_shaders.size() != 1) return 65;
        const auto& color = shader.properties->at(0);
        if (color.name != "_Color" || color.property_type != sl_parser::PropertyDecl::Type::Color ||
            color.default_numbers.size() != 4) return 65;
        const std::array<double,4> expected{0.1,0.3,0.5,1.0};
        for (std::size_t i = 0; i < expected.size(); ++i) {
            if (std::abs(color.default_numbers[i] - expected[i]) > 0.00001) return 65;
        }
        const auto& passes = shader.sub_shaders.at(0).passes;
        if (passes.size() != 1) return 65;
        const auto *pass = dynamic_cast<const sl_parser::Pass*>(passes.at(0).get());
        if (!pass || !pass->shader_program ||
            pass->shader_program->language != sl_parser::ShaderProgram::Language::HLSL) return 65;
        std::ofstream program("bound.frag.hlsl");
        program << pass->shader_program->program;
        if (!program) return 74;
        std::cout << color.display_name << '\n';
        return 0;
    } catch (const std::exception& err) {
        std::cerr << err.what() << '\n';
        return 1;
    }
}

